import{_ as e,c as a,o,al as i}from"./chunks/framework.D8UyiDWg.js";const c=JSON.parse('{"title":"Drive Modes","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_modes_rover/index.md","filePath":"ko/flight_modes_rover/index.md"}'),r={name:"ko/flight_modes_rover/index.md"};function d(s,t,n,l,h,m){return o(),a("div",null,t[0]||(t[0]=[i('<h1 id="drive-modes" tabindex="-1">Drive Modes <a class="header-anchor" href="#drive-modes" aria-label="Permalink to &quot;Drive Modes&quot;">​</a></h1><p>Flight modes (or more accurately &quot;Drive modes&quot; for ground vehicles) provide autopilot support to make it easier to manually drive the vehicle or to execute autonomous missions.</p><p>This section outlines all supported drive modes for <a href="./../frames_rover/">Rovers</a>.</p><p>For information on mapping RC control switches to specific modes see: <a href="./../config/flight_mode.html">Basic Configuration &gt; Flight Modes</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Selecting any other mode than those listed below will either stop the rover or can lead to undefined behaviour.</p></div><h2 id="manual-modes" tabindex="-1">Manual Modes <a class="header-anchor" href="#manual-modes" aria-label="Permalink to &quot;Manual Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>설명</th></tr></thead><tbody><tr><td><a href="./manual.html#manual-mode">Manual</a></td><td>No autopilot support. User is responsible for keeping the rover on the desired course and maintaining speed and rate of turn.</td></tr><tr><td><a href="./manual.html#acro-mode">Acro</a></td><td>+ Maintains the yaw rate (feels more like driving a car than manual mode). <br>+ Allows maximum yaw rate to be limited (protects against roll over).</td></tr><tr><td><a href="./manual.html#stabilized-mode">Stabilized</a></td><td>+ Maintains the yaw (significantly better at holding a straight line).</td></tr><tr><td><a href="./manual.html#position-mode">Position</a></td><td>+ Maintains the course (best mode for driving a straight line).<br>+ Maintains speed against disturbances, e.g. when driving up a hill.<br>+ Allows maximum speed to be limited.</td></tr></tbody></table><h2 id="auto-modes" tabindex="-1">Auto Modes <a class="header-anchor" href="#auto-modes" aria-label="Permalink to &quot;Auto Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>설명</th></tr></thead><tbody><tr><td><a href="./auto.html#mission-mode">Mission</a></td><td>Automatic mode that causes the vehicle to execute a predefined mission.</td></tr><tr><td><a href="./auto.html#return-mode">Return</a></td><td>Automatic mode that returns the vehicle to the launch position.</td></tr></tbody></table>',9)]))}const p=e(r,[["render",d]]);export{c as __pageData,p as default};
